window.RP_SESSION={"id":"S-408af38870e8","messages":[{"id":"RP-III-0060226","time":"2026-03-30T12:02:00+09:00","room":"RP III","name":"배블스 / 작별 서술","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"그동안 즐거웠네. 미물과 어울리는 것은 참으로 귀중하고도 즐거운 경험이었소...\"\n\n\"내가 친애하는 자의 작별인사로 마무리짓도록 할까, good afternoon, good evening, and good night.\"\n\n배블스가 발광하는 소리가 들리지 않는 첫 아침이군요.\n\n그의 오리발은 뜨내기 소매치기의 허리춤에 매달려 있고요,\n\n세상은 그의 이름을 기억할 겁니다. 선구자로, 혹은 그저 괴짜로.\n\n세상은 그의 이름을 잊을 겁니다. 또 하나의 삶이 그렇게 우주 속으로 사라집니다.","characters":["P-4e086d6985d3"]},{"id":"RP-III-0060227","time":"2026-03-30T12:02:00+09:00","room":"RP III","name":"배블스 / 작별 서술","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-4e086d6985d3"]},{"id":"RP-III-0060228","time":"2026-03-30T12:02:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
